    internal static string T(string key) => Messages.TryGetValue(key, out var text) ? Loc.Language == "tr" ? text.Tr : text.En : key;
    internal static ResourceDictionary Resources()
    {
        var result = new ResourceDictionary(); foreach (string key in Messages.Keys) result["Workbench" + key] = T(key); return result;
    }
